from rcb_client import Robot
import numpy as np
from PIL import Image
r=Robot(); rr=np.array(r.spec()['qpos']['range']); lo,hi=rr[:,0],rr[:,1]
def norm(x): return np.clip(2*(np.asarray(x)-lo)/(hi-lo)-1,-1,1)
o=r.observe(images=False); q=np.array(o['proprio']['joint_pos']); base=q.copy();
def block(start,end,n):
 rows=np.array([norm(start+(end-start)*(k+1)/n) for k in range(n)])
 return r.step('qpos',rows,images=False)
t=q.copy(); t[2]=-.1; t[3]=1.1; t[4]=-.65; t[11]=-.25; t[15]=-.25
for a,b,n in [(q,t,8),(t,t,6)]:
 o=block(a,b,n); print('block',o['step'],o['imu'],np.round(o['proprio']['joint_pos'][:10],2))
o=r.observe(images=['room_camera']); Image.fromarray(o['images']['room_camera']).save('/tmp/small1.png')
print('status',r.status())
